    @push('scripts')
        <script src="{{ asset('AdminLTE-3.2.0/plugins/datatables/jquery.dataTables.min.js') }}"></script><script src="{{ asset('AdminLTE-3.2.0/plugins/datatables-bs4/js/dataTables.bootstrap4.min.js') }}"></script>
        <script src="{{ asset('AdminLTE-3.2.0/plugins/select2/js/select2.full.min.js') }}"></script><script src="{{ asset('AdminLTE-3.2.0/plugins/sweetalert2/sweetalert2.min.js') }}"></script>
        <script>
        $(function(){
            const table=$('#variants-table').DataTable({processing:true,serverSide:true,autoWidth:false,ajax:"{{ route('admin.product-variants.data') }}",columns:[
                {data:'DT_RowIndex',name:'DT_RowIndex',orderable:false,searchable:false},{data:'name',name:'product_variants.name'},{data:'group_name',name:'product_groups.name'},{data:'description',name:'product_variants.description',defaultContent:'-'},{data:'price_display',name:'product_variants.price',searchable:false},{data:'discount_display',name:'product_variants.discount_price',searchable:false,orderable:false},{data:'sort_order',name:'product_variants.sort_order'},{data:'status',name:'product_variants.is_active',searchable:false},{data:'created_at',name:'product_variants.created_at'},{data:'actions',name:'actions',orderable:false,searchable:false}
            ],order:[[6,'asc']],language:{processing:'Memproses...',search:'Cari:',lengthMenu:'Tampilkan _MENU_ data',info:'Menampilkan _START_–_END_ dari _TOTAL_ data',infoEmpty:'Belum ada data Product Variant',infoFiltered:'(difilter dari _MAX_ total data)',zeroRecords:'Product Variant tidak ditemukan',emptyTable:'Belum ada Product Variant. Silakan tambahkan data pertama.',paginate:{first:'Pertama',last:'Terakhir',next:'Berikutnya',previous:'Sebelumnya'}}});
            const modal=$('#variant-modal'),form=$('#variant-form'),errors=$('#form-errors'),save=$('#btn-save-variant');
            $('#product_group_id').select2({theme:'bootstrap4',dropdownParent:modal,placeholder:'Cari Product Group',allowClear:true,width:'100%'});
            function refreshVariantItems(){const cards=$('#variant-items .variant-item-card');cards.each(function(index){$(this).find('.variant-item-number').text('Variant '+(index+1));$(this).find('[data-variant-key]').each(function(){$(this).attr('name',`variants[${index}][${$(this).attr('data-variant-key')}]`);});$(this).find('.variant-remove').prop('disabled',cards.length===1);});$('#btn-add-name').prop('disabled',cards.length>=50);}
            function addVariantInput(item={}){if($('#variant-items .variant-item-card').length>=50)return;const index=$('#variant-items .variant-item-card').length;const card=$('<div class="card card-outline card-primary variant-item-card mb-2"></div>');const header=$('<div class="card-header d-flex align-items-center justify-content-between"></div>');header.append('<strong class="variant-item-number"></strong>');const remove=$('<button>',{type:'button',class:'btn btn-outline-danger btn-xs variant-remove',title:'Hapus variant'}).html('<i class="fas fa-trash"></i> Hapus');header.append(remove);const body=$('<div class="card-body"></div>');const row=$('<div class="row"></div>');
                const makeField=(label,key,placeholder,required)=>{const col=$('<div class="col-4 col-md-4"></div>');const group=$('<div class="form-group"></div>');group.append($('<label>').text(label));const input=$('<input>',{class:'form-control',name:`variants[${index}][${key}]`,type:key==='name'?'text':'number',maxlength:key==='name'?150:undefined,min:key==='name'?undefined:0,step:key==='name'?undefined:'0.01',required:!!required,placeholder,'data-variant-key':key});if(item[key]!==undefined&&item[key]!==null)input.val(item[key]);group.append(input);if(key==='discount_price')group.append('<small class="form-text text-muted">Opsional</small>');col.append(group);row.append(col);};
                makeField('Nama Variant','name','Contoh: 100 Diamond',true);makeField('Harga (Rp)','price','35000',true);makeField('Harga Promo (Rp)','discount_price','Opsional',false);body.append(row);card.append(header,body);$('#variant-items').append(card);refreshVariantItems();}
            function reset(){form[0].reset();$('#product_group_id').val('').trigger('change');$('#variant-items').empty();addVariantInput();errors.addClass('d-none').empty();$('#sort_order_custom').val('0');$('#sort_order').val(0);form.find('input[name="_method"]').remove();save.prop('disabled',false);}
            $('#btn-add-name').on('click',()=>addVariantInput());$('#variant-items').on('click','.variant-remove',function(){$(this).closest('.variant-item-card').remove();refreshVariantItems();});
            $('#btn-add-variant').on('click',function(){reset();form.attr('action',"{{ route('admin.product-variants.store') }}");$('#modal-title').text('Tambah Product Variant');save.find('span').text('Simpan Variant');modal.modal('show');});
            $('#sort_order').on('input',()=>$('#sort_order_custom').val('1'));modal.on('hidden.bs.modal',reset);
            $('#variants-table').on('click','[data-action="edit"]',function(){const row=table.row($(this).closest('tr')).data();if(!row)return;reset();form.attr('action',"{{ route('admin.product-variants.update', ':id') }}".replace(':id',row.id));form.append('<input type="hidden" name="_method" value="PUT">');$('#modal-title').text('Edit Product Variant');save.find('span').text('Simpan Perubahan');$('#product_group_id').val(String(row.product_group_id)).trigger('change');$('#variant-items').empty();addVariantInput({name:row.name,price:row.price,discount_price:row.discount_price});$('#description').val(row.description||'');$('#sort_order').val(row.sort_order);$('#sort_order_custom').val('0');$('#is_active').val(row.is_active?'1':'0');modal.modal('show');});
            form.on('submit',function(e){e.preventDefault();errors.addClass('d-none').empty();save.prop('disabled',true);$.ajax({url:form.attr('action'),method:'POST',data:form.serialize(),headers:{Accept:'application/json'}}).done(function(resp){modal.modal('hide');table.ajax.reload(null,false);Swal.fire({icon:'success',title:'Berhasil',text:resp.message,timer:1700,showConfirmButton:false});}).fail(function(xhr){if(xhr.status===422&&xhr.responseJSON?.errors){errors.html(Object.values(xhr.responseJSON.errors).flat().map(msg=>`<div>${$('<div>').text(msg).html()}</div>`).join('')).removeClass('d-none');}else{Swal.fire({icon:'error',title:'Gagal',text:xhr.responseJSON?.message||'Product Variant gagal disimpan.'});}}).always(()=>save.prop('disabled',false));});
            $('#variants-table').on('click','[data-action="delete"]',function(){const row=table.row($(this).closest('tr')).data();if(!row)return;Swal.fire({icon:'warning',title:'Hapus Product Variant?',text:`Data "${row.name}" akan dihapus.`,showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal',confirmButtonColor:'#dc3545'}).then(result=>{if(!result.isConfirmed)return;$.ajax({url:"{{ route('admin.product-variants.destroy', ':id') }}".replace(':id',row.id),method:'POST',data:{_token:$('meta[name="csrf-token"]').attr('content'),_method:'DELETE'},headers:{Accept:'application/json'}}).done(resp=>{table.ajax.reload(null,false);Swal.fire({icon:'success',title:'Berhasil',text:resp.message,timer:1700,showConfirmButton:false});}).fail(xhr=>Swal.fire({icon:'error',title:'Gagal',text:xhr.responseJSON?.message||'Product Variant gagal dihapus.'}));});});
        });
        </script>
    @endpush
</x-app-layout>
